def poisoned(b):
    n = 0
    for c in b.legal:
        r = b.landing(c)
        if r + 1 < 6 and (r + 1, c) in b.their_wins and (r, c) not in b.my_wins and (r, c) not in b.their_wins:
            n += 1
    return n

def fires(b):
    return b.ply >= 18 and poisoned(b) > 0

def level(b):
    if not fires(b):
        return 0
    return min(9, 3 + (b.ply - 18) // 3 + (2 if b.heights[4] == 6 else 0))

def parity_threat(b):
    want = 0 if not b.me_first else 1
    return any(r % 2 == want for (r, c) in b.their_wins)

def fires(b):
    return b.heights[4] == 6 and parity_threat(b)

def level(b):
    if b.heights[4] < 6:
        return 0
    s = 3 if parity_threat(b) else 1
    s += 2 * (b.heights[5] == 6) + 2 * (b.heights[3] == 6)
    return min(9, s)

def vert_block(b):
    for (r, c) in b.their_playable_wins:
        if c in (3, 4, 5) and r >= 3 and all(b.grid[r - k][c] == 2 for k in (1, 2, 3)):
            return True
    return False

def late(b):
    return b.heights[4] == 6 and b.heights[5] == 6 and b.heights[1] < 6 and b.heights[2] < 6

def fires(b):
    return late(b) or vert_block(b)

def level(b):
    if vert_block(b):
        return 6
    if b.heights[4] < 6:
        return 0
    s = 2
    if b.heights[5] == 6:
        s += 2
    if b.heights[1] < 6 and b.heights[2] < 6:
        s += 2
    if b.heights[3] == 6 or b.heights[6] == 6:
        s += 1
    if b.heights[0] == 6:
        s += 1
    if b.ply % 2 == 1:
        s += 1
    return min(9, s)

def control(b):
    mine = 0
    theirs = 0
    for c in b.legal:
        for r in range(b.landing(c), 6):
            t = (r, c) in b.their_wins
            m = (r, c) in b.my_wins
            if t or m:
                if t and not m:
                    theirs += 1
                elif m and not t:
                    mine += 1
                break
    return mine, theirs

def fires(b):
    if b.heights[4] < 6:
        return False
    m, t = control(b)
    return t > m

